#!/usr/bin/env python3
"""Generate the project's own INI from its frozen native tuning layout."""
import sys,json
from pathlib import Path
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'tools'))
from engine_protocol import NUMBERS,FLAGS,CURVES,SIGNATURE,PAGE_SIZES,LIVE_FIELDS,REVISION_OFFSET,TIMING_FIELDS,field_units,LIVE_BYTES
from idle_config import ALGORITHMS,SCALARS,ARRAYS,SCALAR_OFFSETS,ARRAY_OFFSETS,OFFSET,UNITS,LIMITS,name as idle_name
from transient_config import MODES,MODE_LABELS,APPLIES,APPLY_LABELS,SCALARS as AE_SCALARS,ARRAYS as AE_ARRAYS,SCALAR_OFFSETS as AE_SCALAR_OFFSETS,ARRAY_OFFSETS as AE_ARRAY_OFFSETS,OFFSET as AE_OFFSET,UNITS as AE_UNITS,LIMITS as AE_LIMITS,LIVE_NAMES as AE_LIVE_NAMES,LIVE_UNITS as AE_LIVE_UNITS,name as ae_name
from load_config import ENUM_FIELDS as LOAD_ENUM_FIELDS,SCALARS as LOAD_SCALARS,ENUM_OFFSETS as LOAD_ENUM_OFFSETS,SCALAR_OFFSETS as LOAD_SCALAR_OFFSETS,LABELS as LOAD_LABELS,UNITS as LOAD_UNITS,LIMITS as LOAD_LIMITS,LIVE_NAMES as LOAD_LIVE_NAMES,LIVE_UNITS as LOAD_LIVE_UNITS,OFFSET as LOAD_OFFSET,ENUMS as LOAD_ENUMS,VALUE_NAMES as LOAD_VALUE_NAMES,AFR_STATES as LOAD_AFR_STATES,name as load_name
s=['; Generated by scripts/generate_tunerstudio_ini.py. Own ECU identity; not Speeduino firmware.','[MegaTune]',' MTversion = 2.25',' queryCommand = "Q"',f' signature = "{SIGNATURE.decode()}"',' versionInfo = "S"','[TunerStudio]',' iniSpecVersion = 3.64','[Constants]',' endianness = little',' nPages = 1',f' pageSize = {PAGE_SIZES[1]}',' pageIdentifier = "\\$tsCanId\\x01"']
for key,value in [('pageReadCommand','p%2i%2o%2c'),('pageChunkWrite','M%2i%2o%2c%v'),('pageValueWrite','M%2i%2o%2c%v'),('burnCommand','b%2i'),('crc32CheckCommand','d%2i')]:s.append(' '+key+' = '+', '.join('"'+value+'"' for _ in range(1)))
s+=[' blockingFactor = 256',' messageEnvelopeFormat = msEnvelope_1.0',' tsWriteBlocks = on',' delayAfterPortOpen = 100',' blockReadTimeout = 2000',' page = 1']
for i,k in enumerate(FLAGS):s.append(f' {k} = bits, U32, 0, [{i}:{i}], "Off", "On"')
for i,(group,k) in enumerate(NUMBERS):
 unit=field_units(k)
 lo,hi=-1000,10000
 if k=='idle_target_rpm':lo,hi=600,1500
 elif k in ('idle_kp','idle_ki'):lo,hi=0,.2
 s.append(f' {k} = scalar, F32, {4+4*i}, "{unit}", 1, 0, {lo}, {hi}, 3')
offset=4+4*len(NUMBERS)
for k,n in CURVES:s.append(f' {k} = array, F32, {offset}, [{n}], "", 1, 0, -1000, 1000, 3');offset+=n*4
s.append(f' baseRevision = scalar, U32, {REVISION_OFFSET}, "", 1, 0, 1, 4294967295, 0')
s.append(' engineStrategy = bits, U32, 272, [0:1], "Batch / wasted", "Sequential", "Semi-sequential", "INVALID"')
for name,offset in TIMING_FIELDS:s.append(f' {name} = scalar, F32, {offset}, "deg", 1, 0, 0, 719, 2')
for i in range(4):s.append(f' fireOrder{i+1} = scalar, U08, {288+i}, "", 1, 0, 1, {1 if i==0 else 4}, 0')
for page,key,units,lo,hi in [(2,'ve','%',0,255),(3,'spark','deg',-5,40),(4,'lambda','lambda',.75,1.2)]:
 offset={2:512,3:1664,4:2816}[page]
 s += [f' {key}Rpm = array, F32, {offset}, [16], "RPM", 1, 0, 50, 10000, 0',f' {key}Load = array, F32, {offset+64}, [16], "source_units", 1, 0, 0, 600, 2',f' {key}Table = array, F32, {offset+128}, [16x16], "{units}", 1, 0, {lo}, {hi}, 2']
s += ['; Complete-tune staging. Any successful burn activates and resets control.']
s.append(' cylinderTrimsEnabled = bits, U32, 4752, [0:0], "Off", "On"')
for cylinder in range(4):
 prefix=f'c{cylinder+1}'
 s += [f' {prefix}SparkTrim = scalar, F32, {4736+cylinder*4}, "deg", 1, 0, -10, 10, 2',
       f' {prefix}FuelRpm = array, F32, {3968+192*cylinder}, [6], "RPM", 1, 0, 50, 10000, 0',
       f' {prefix}FuelLoad = array, F32, {3992+192*cylinder}, [6], "source_units", 1, 0, 0, 600, 2',
       f' {prefix}FuelTable = array, F32, {4016+192*cylinder}, [6x6], "%", 1, 0, 50, 150, 2']
s.append(f' iac_algorithm = bits, U32, {OFFSET}, [0:1], '+', '.join('"'+a+'"' for a in ALGORITHMS))
for name in SCALARS:
 lo,hi=LIMITS[name];s.append(f' {idle_name(name)} = scalar, F32, {SCALAR_OFFSETS[name]}, "{UNITS[name]}", 1, 0, {lo}, {hi}, 3')
for name,n in ARRAYS:
 lo,hi=LIMITS[name];s.append(f' {idle_name(name)} = array, F32, {ARRAY_OFFSETS[name]}, [{n}], "{UNITS[name]}", 1, 0, {lo}, {hi}, 2')
s.append(' ae_mode = bits, U32, 4992, [0:1], '+', '.join('"'+v+'"' for v in MODE_LABELS))
s.append(' ae_apply = bits, U32, 4996, [0:0], '+', '.join('"'+v+'"' for v in APPLY_LABELS))
for name in AE_SCALARS:
 lo,hi=AE_LIMITS[name];s.append(f' {ae_name(name)} = scalar, F32, {AE_SCALAR_OFFSETS[name]}, "{AE_UNITS[name]}", 1, 0, {lo}, {hi}, 3')
for name in AE_ARRAYS:
 lo,hi=AE_LIMITS[name];s.append(f' {ae_name(name)} = array, F32, {AE_ARRAY_OFFSETS[name]}, [4], "{AE_UNITS[name]}", 1, 0, {lo}, {hi}, 3')
for name in LOAD_ENUM_FIELDS:
 labels=list(LOAD_LABELS[name]);width=(len(labels)-1).bit_length();labels+=['INVALID']*((1<<width)-len(labels))
 s.append(f' {load_name(name)} = bits, U32, {LOAD_ENUM_OFFSETS[name]}, [0:{width-1}], '+', '.join('"'+v+'"' for v in labels))
for name in LOAD_SCALARS:
 lo,hi=LOAD_LIMITS[name];s.append(f' {load_name(name)} = scalar, F32, {LOAD_SCALAR_OFFSETS[name]}, "{LOAD_UNITS[name]}", 1, 0, {lo}, {hi}, 3')
s+=['[ConstantsExtensions]',' readOnly = baseRevision',' defaultValue = baseRevision, 1','[OutputChannels]',' ochGetCommand = "r\\$tsCanId\\x30%2o%2c"',f' ochBlockSize = {LIVE_BYTES}']
for i,k in enumerate(LIVE_FIELDS):s.append(f' {k} = scalar, F32, {i*4}, "", 1, 0')
for offset,k in [(44,'faults'),(48,'sync'),(52,'physicalInhibited'),(56,'revision'),(60,'dataSource'),(64,'snapshotAgeMs'),(68,'simulationComplete'),(72,'hasResult'),(76,'crankSynced'),(80,'phaseSynced'),(84,'phaseRequired'),(88,'phaseLosses'),(92,'strategy'),(96,'camRejected')]:s.append(f' {k} = scalar, U32, {offset}, "", 1, 0')
for cylinder in range(4):
 for field,unit,part in [('PW','ms',0),('Advance','deg',1),('FuelTrim','%',2),('Duty','%',3)]:s.append(f' c{cylinder+1}{field} = scalar, F32, {100+cylinder*16+part*4}, "{unit}", 1, 0')
for index,name in enumerate(['cylinderValidMask','cylinderTrimsActive','cylinderCapacityMask','cylinderSparkClampMask','cylinderRetardFloorMask']):s.append(f' {name} = scalar, U32, {164+index*4}, "", 1, 0')
for index,name in enumerate(['activeRevision','sessionOriginRevision','sessionBaseRevision','stagedDirty','tuningWriteState','tuningLastCode','inputValidMask','observationFlags']):s.append(f' {name} = scalar, U32, {184+index*4}, "", 1, 0')
for index,name in enumerate(['iacTarget','iacFeedforward','iacP','iacI','iacD','iacDuty']):s.append(f' {name} = scalar, F32, {216+index*4}, "{ "RPM" if index==0 else "%"}", 1, 0')
for index,name in enumerate(['iacFlags','iacState','iacReason','iacAlgorithm']):s.append(f' {name} = scalar, U32, {240+index*4}, "", 1, 0')
s.append(' iacAvailable = bits, U32, 240, [8:8], "Unavailable", "Available"')
for i,name in enumerate(AE_LIVE_NAMES):s.append(f' {name} = scalar, F32, {256+i*4}, "{AE_LIVE_UNITS[i]}", 1, 0')
for i,name in enumerate(('aeFlags','aeMode','aeApply','aePhase','aeReason')):s.append(f' {name} = scalar, U32, {288+i*4}, "", 1, 0')
s+=[' aeAvailable = bits, U32, 288, [8:8], "Unavailable", "Available"',' aeRateValid = bits, U32, 288, [0:0], "Unavailable", "Valid"']
for i,name in enumerate(LOAD_LIVE_NAMES):s.append(f' {name} = scalar, F32, {320+i*4}, "{LOAD_LIVE_UNITS[i]}", 1, 0')
for i,name in enumerate(('loadFlags','loadFuelSource','loadSparkSource','loadLambdaSource','loadTrimSource','loadPressureMode','loadAuxRole','loadBaroSource','loadAfrMode')):s.append(f' {name} = scalar, U32, {356+i*4}, "", 1, 0')
s+=[' loadAvailable = bits, U32, 356, [16:16], "Unavailable", "Available"',' loadAfrAvailable = bits, U32, 356, [17:17], "Not evaluated", "Evaluated"',' loadReason = bits, U32, 356, [24:26], "Unavailable", "Ready", "Invalid configuration", "Required MAP missing", "Required TPS missing", "Required EMAP missing", "Required baro missing", "Known MAP above NA limit"',' loadAfrState = bits, U32, 356, [13:15], "Off or not evaluated", "Target incorporation", "Running delay", "Cranking neutral", "Wideband unavailable", "Measured ratio", "Invalid target", "Running clock unavailable"']
groups={
 'engineLoad':('Load sources, table bases, pressure and AFR',[load_name(k) for k in LOAD_ENUM_FIELDS+LOAD_SCALARS]),
 'cylinderTrims':('Physical cylinder trims',['cylinderTrimsEnabled']+[f'c{i}SparkTrim' for i in range(1,5)]),
 'engineTiming':('Cycle and cam phase',['engineStrategy','cylinderTrimsEnabled','fireOrder1','fireOrder2','fireOrder3','fireOrder4','injection_end_deg','cam_sync_deg','cam_window_deg']),
 'engineSettings':('Engine and output limits',[k for group,k in NUMBERS if group=='engine']+['cranking_rpm','tooth1_btdc_deg','max_injection_ms','max_dwell_ms']),
 'engineEnrichment':('Starting and fuel corrections',['crank_advance_deg','afterstart_pct','afterstart_s','accel_threshold_pct_s','accel_gain','accel_decay_s','ego_enabled','ego_kp','ego_ki','ego_limit','ego_min_clt']),
 'engineTransient':('TPS or MAP transient enrichment',['ae_mode','ae_apply']+[ae_name(k) for k in AE_SCALARS]),
 'engineProtection':('Rev limit and overrun cut',['rpm_limit','rpm_hysteresis','soft_limit_band','max_duty','dfco_enabled','dfco_rpm','dfco_hysteresis','dfco_tps','dfco_delay_s']),
 'engineAux':('Fan and pump proposals',['fan_on_c','fan_off_c','pump_prime_s']),
 'engineIdle':('Idle air / normally closed 2-wire PWM',['idle_enabled','idle_target_rpm','idle_kp','idle_ki','iac_algorithm']+[idle_name(k) for k in SCALARS]),
}
s+=['[Menu]',' menuDialog = main',' menu = "Engine development"']
for key,(label,fields) in groups.items():s.append(f' subMenu = {key}, "{label} (development)"')
for key,label in [('ve','Fuel coefficient map'),('spark','Spark map'),('lambda','Lambda target')]:s.append(f' subMenu = {key}Editor, "{label}"')
for key,label in [('warmup','Warmup enrichment'),('crank','Cranking enrichment'),('deadtime','Injector dead time'),('dwell','Coil dwell')]:s.append(f' subMenu = {key}Curve, "{label}"')
for key,label in [('run_pct','Idle running feedforward'),('crank_pct','Idle cranking duty'),('target_add_rpm','Idle target addition')]:s.append(f' subMenu = iac_{key}Curve, "{label}"')
for key in ('tps','map'):s.append(f' subMenu = ae_{key}Curve, "{key.upper()} rate enrichment"')
for i in range(1,5):s.append(f' subMenu = c{i}FuelEditor, \"Cylinder {i} fuel trim %\"')
s+=['[UiDialogs]']
for key,(label,fields) in groups.items():
 s.append(f' dialog = {key}, "{label} / INHIBITED; BURN RESTARTS CONTROL"')
 for field in fields:s.append(f' field = "{field.replace("_"," ")}", {field}')
s+=['[CurveEditor]']
for key,label,axis,values,units in [('warmup','Warmup enrichment','coolant_c','warmup_pct','%'),('crank','Cranking enrichment','coolant_c','crank_pct','%'),('deadtime','Injector dead time','battery_v','deadtime_ms','ms'),('dwell','Coil dwell','battery_v','dwell_ms','ms')]:
 s += [f' curve = {key}Curve, "{label} (development)"',f' columnLabel = "{axis}", "{label} ({units})"',f' xBins = {axis}',f' yBins = {values}']
for key,label,units in [('run_pct','Idle running feedforward','%'),('crank_pct','Idle cranking duty','%'),('target_add_rpm','Idle target addition','RPM')]:
 s += [f' curve = iac_{key}Curve, "{label} / development"',f' columnLabel = "Coolant (C)", "{label} ({units})"',' xAxis = -40, 140, 7',f' yAxis = {"-500, 1000, 7" if key=="target_add_rpm" else "0, 100, 6"}',' size = 650, 300',' xBins = iac_coolant_c',f' yBins = iac_{key}']
for key in ('tps','map'):
 s += [f' curve = ae_{key}Curve, "{key.upper()} rate / proposed extra fuel percent"',' columnLabel = "Rate", "Extra fuel"',' xAxis = 0, 2550, 6',' yAxis = 0, 255, 6',' size = 650, 300',f' xBins = ae_{key}_rates, ae{key.title()}Dot',f' yBins = ae_{key}_added_pct']
s+=['[TableEditor]']
for k,label,channel in [('ve','Fuel coefficient','loadFuel'),('spark','Spark advance','loadSpark'),('lambda','Lambda target','loadLambda')]:
 s += [f' table = {k}Editor, {k}Map, "{label} / declared table basis", 1',f' xBins = {k}Rpm, rpm',f' yBins = {k}Load, {channel}',f' zBins = {k}Table',f' upDownLabel = "{label}"',f' gridHeight = 2.0',f' gridOrient = 250, 0, 340']
for i in range(1,5):
 s += [f' table = c{i}FuelEditor, c{i}FuelMap, \"Cylinder {i} fuel trim / declared basis / sequential only\", 1',f' xBins = c{i}FuelRpm, rpm',f' yBins = c{i}FuelLoad, loadTrim',f' zBins = c{i}FuelTable',f' upDownLabel = \"Fuel percent, 100 neutral\"', ' gridHeight = 2.0',' gridOrient = 250, 0, 340']
s+=['[GaugeConfigurations]',' rpmGauge = rpm, "Engine speed", "RPM", 0, 8000, 0, 0, 6500, 8000, 0, 0',' mapGauge = map_kpa, "Manifold pressure", "kPa", 0, 110, 0, 10, 105, 110, 1, 1',' pwGauge = pulse_ms, "Proposed injection", "ms", 0, 15, 0, 0, 14, 15, 2, 2',' advanceGauge = advance_deg, "Proposed advance", "deg", -5, 40, -5, 0, 35, 40, 1, 1','[FrontPage]',' gauge1 = rpmGauge',' gauge2 = mapGauge',' gauge3 = pwGauge',' gauge4 = advanceGauge',' indicator = { physicalInhibited }, "INHIBITED; BURN RESTARTS CONTROL", "INHIBITED; BURN RESTARTS CONTROL", yellow, black, yellow, black',' indicator = { hasResult }, "NO CONTROL SAMPLE", "SAMPLE: CHECK SOURCE AND AGE", gray, black, yellow, black','[Datalog]']
for k in LIVE_FIELDS:s.append(f' entry = {k}, "{k}", float, "%.4f"')
for cylinder in range(1,5):
 for field in ('PW','Advance','FuelTrim','Duty'):s.append(f' entry = c{cylinder}{field}, "C{cylinder}{field}", float, "%.4f"')
for name in ('cylinderValidMask','cylinderTrimsActive','cylinderCapacityMask','cylinderSparkClampMask','cylinderRetardFloorMask'):s.append(f' entry = {name}, "{name}", int, "%d"')
s+=[' entry = faults, "Faults", int, "%d"',' entry = physicalInhibited, "PhysicalInhibited", int, "%d"']
for name in ['iacTarget','iacFeedforward','iacP','iacI','iacD','iacDuty','iacFlags','iacState','iacReason','iacAlgorithm']:s.append(f' entry = {name}, "{name}", float, "%.4f"')
for name in ('iacAvailable','dataSource','snapshotAgeMs','inputValidMask','observationFlags','activeRevision','sessionOriginRevision','tuningWriteState'):s.append(f' entry = {name}, "{name}", int, "%d"')
for name in (*AE_LIVE_NAMES,'aeFlags','aeMode','aeApply','aePhase','aeReason','aeAvailable','aeRateValid'):s.append(f' entry = {name}, "{name}", float, "%.4f"')
for name in (*LOAD_LIVE_NAMES,'loadFlags','loadFuelSource','loadSparkSource','loadLambdaSource','loadTrimSource','loadPressureMode','loadAuxRole','loadBaroSource','loadAfrMode','loadAvailable','loadAfrAvailable','loadReason','loadAfrState'):s.append(f' entry = {name}, "{name}", float, "%.4f"')
(R/'tuning/esp32-ecu-load.ini').write_text('\n'.join(s)+'\n')
(R/'tuning/protocol-layout.json').write_text(json.dumps(dict(signature=SIGNATURE.decode(),pages=PAGE_SIZES,numeric_fields=NUMBERS,flags=FLAGS,curves=CURVES,idle_scalars=SCALAR_OFFSETS,idle_arrays=ARRAY_OFFSETS,transient_scalars=AE_SCALAR_OFFSETS,transient_arrays=AE_ARRAY_OFFSETS,transient_offset=AE_OFFSET,transient_live_fields=AE_LIVE_NAMES,load_enum_offsets=LOAD_ENUM_OFFSETS,load_scalar_offsets=LOAD_SCALAR_OFFSETS,load_enums=LOAD_ENUMS,load_live_offset=320,load_live_values=LOAD_VALUE_NAMES,load_live_fields=LOAD_LIVE_NAMES,load_afr_states=LOAD_AFR_STATES,load_flag_available_bit=16,load_flag_afr_available_bit=17,load_reason_shift=24,live_fields=LIVE_FIELDS,live_block_bytes=LIVE_BYTES,timing_fields=TIMING_FIELDS,strategy_offset=272,firing_order_offset=288,revision_offset=REVISION_OFFSET,serial_protocol='002',page_offsets=dict(header=0,ve=512,spark=1664,lambda_target=2816,cylinder=3968,idle=OFFSET),origin_revision_read_only=True,commit_behavior='whole-tune stage; burn persists/activates and resets control; stable session origin',scope='shared native and inhibited target USB Serial/JTAG; UART0 diagnostics separate; physical USB unmeasured; TunerStudio own-identity online gate unresolved'),indent=2)+'\n')
print('Generated own TunerStudio INI and wire-layout manifest')
